    max_insert_steps = 25
    for i in range(max_insert_steps):
        vis = call("vision", "locate")
        hole, peg = parse_vision(vis)
        fr = call("robot", "force", "right")
        f = parse_force(fr)
        if peg and f:
            log(f"  insert step {i}: peg_lz={peg['lz']:.2f}, hole_top={hole['top_z'] if hole else '?'}, Fz={f['Fz']:.1f}")
