import subprocess, json, re, sys, time, math

def call(*args, timeout=40):
    try:
        res = subprocess.run(args, capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        return {"ok": False, "text": f"TIMEOUT: {args}"}
    out = res.stdout.strip()
    if not out:
        out = res.stderr.strip()
    try:
        j = json.loads(out)
        return j
    except Exception:
        return {"ok": False, "text": out, "raw_stdout": res.stdout, "raw_stderr": res.stderr}

def parse_vision(j):
    t = j.get("text", "")
    m = re.search(r'socket hole centre: x=([-0-9.]+) y=([-0-9.]+) mm, top at z=([-0-9.]+) mm', t)
    hole = None
    if m:
        hole = {"x": float(m.group(1)), "y": float(m.group(2)), "top_z": float(m.group(3))}
    peg = None
    m = re.search(r'peg: centre x=([-0-9.]+) y=([-0-9.]+) z=([-0-9.]+) mm; lower end x=([-0-9.]+) y=([-0-9.]+) z=([-0-9.]+) mm; tilt ([-0-9.]+) deg', t)
    if m:
        peg = {
            "cx": float(m.group(1)), "cy": float(m.group(2)), "cz": float(m.group(3)),
            "lx": float(m.group(4)), "ly": float(m.group(5)), "lz": float(m.group(6)),
            "tilt": float(m.group(7))
        }
    return hole, peg

def parse_status(j):
    t = j.get("text", "")
    out = {}
    m = re.search(r'left arm: TCP at x=([-0-9.]+) y=([-0-9.]+) z=([-0-9.]+) mm; gripper (empty|closed on an object)', t)
    if m:
        out["left"] = {"x": float(m.group(1)), "y": float(m.group(2)), "z": float(m.group(3)), "grip": m.group(4)}
    m = re.search(r'right arm: TCP at x=([-0-9.]+) y=([-0-9.]+) z=([-0-9.]+) mm; gripper (empty|closed on an object)', t)
    if m:
        out["right"] = {"x": float(m.group(1)), "y": float(m.group(2)), "z": float(m.group(3)), "grip": m.group(4)}
    return out

def parse_force(j):
    t = j.get("text", "")
    m = re.search(r'right TCP force estimate: Fx=([-+0-9.]+) Fy=([-+0-9.]+) Fz=([-+0-9.]+) N', t)
    if m:
        return {"Fx": float(m.group(1)), "Fy": float(m.group(2)), "Fz": float(m.group(3))}
    return None

def log(msg):
    print(msg, flush=True)

def step_chunk(arm, dx, dy, dz, max_step=20.0):
    """Move in relative chunks no larger than max_step."""
    remaining = [dx, dy, dz]
    while True:
        if all(abs(v) < 0.01 for v in remaining):
            return True
        cmd_d = []
        for v in remaining:
            if abs(v) <= max_step:
                cmd_d.append(v)
            else:
                cmd_d.append(math.copysign(max_step, v))
        r = call("robot", "step", arm, f"{cmd_d[0]:.3f}", f"{cmd_d[1]:.3f}", f"{cmd_d[2]:.3f}")
        log(f"  step {arm} {cmd_d} -> ok={r.get('ok')} {r.get('text','').strip()}")
        if not r.get("ok"):
            return False
        for i in range(3):
            remaining[i] -= cmd_d[i]

def main():
    log("=== Insertion controller trial ===")
    # 1. Left arm removes cap and places in bin using built-in skills
    r = call("robot", "pick", "cap", "--arm", "left")
    log(f"pick cap left: {r.get('ok')} {r.get('text','').strip()}")
    if not r.get("ok"):
        log("ABORT: cap pick failed")
        sys.exit(1)
    r = call("robot", "place", "bin", "--arm", "left")
    log(f"place cap bin: {r.get('ok')} {r.get('text','').strip()}")
    if not r.get("ok"):
        log("ABORT: cap place failed")
        sys.exit(1)

    # 2. Right arm picks peg from holder
    call("robot", "grip", "right", "open")
    vis = call("vision", "locate")
    hole, peg = parse_vision(vis)
    if peg is None:
        log("ABORT: no peg vision")
        sys.exit(1)
    log(f"Peg vision: centre=({peg['cx']:.1f},{peg['cy']:.1f},{peg['cz']:.1f}), lower=({peg['lx']:.1f},{peg['ly']:.1f},{peg['lz']:.1f}), tilt={peg['tilt']:.1f}")
    # Move above peg, then correct using encoder TCP vs vision
    r = call("robot", "move", "right", f"{peg['cx']:.3f}", f"{peg['cy']:.3f}", "120")
    log(f"move above peg: {r.get('ok')} {r.get('text','').strip()}")
    # correct x/y in up to 4 iterations using vision centre vs TCP from status
    for i in range(4):
        st = parse_status(call("robot", "status"))
        if not st.get("right"):
            break
        tcp = st["right"]
        dx = peg["cx"] - tcp["x"]
        dy = peg["cy"] - tcp["y"]
        log(f"  peg align iter {i}: tcp=({tcp['x']:.2f},{tcp['y']:.2f},{tcp['z']:.2f}) d=({dx:.2f},{dy:.2f})")
        if abs(dx) < 0.4 and abs(dy) < 0.4:
            break
        # clamp for one step call; if big, use move? Here few mm
        if not step_chunk("right", dx, dy, 0):
            log("ABORT: correction step failed")
            sys.exit(1)
    # Lower to grasp height and close
    step_chunk("right", 0, 0, -20)
    step_chunk("right", 0, 0, -20)
    r = call("robot", "grip", "right", "close")
    log(f"grip close peg: {r.get('ok')} {r.get('text','').strip()}")
    st = parse_status(call("robot", "status"))
    if not st.get("right") or st["right"].get("grip") != "closed on an object":
        log("ABORT: right gripper did not close on peg")
        sys.exit(1)
    # Lift peg clear of holder
    step_chunk("right", 0, 0, 20)
    step_chunk("right", 0, 0, 20)

    # 3. Move peg above socket and align lower end with hole centre
    r = call("robot", "move", "right", "0", "60", "140")
    log(f"move above socket: {r.get('ok')} {r.get('text','').strip()}")
    for i in range(6):
        vis = call("vision", "locate")
        hole, peg = parse_vision(vis)
        if hole is None or peg is None:
            log("ABORT: no vision during socket alignment")
            sys.exit(1)
        dx = hole["x"] - peg["lx"]
        dy = hole["y"] - peg["ly"]
        log(f"  socket align iter {i}: peg_lower=({peg['lx']:.2f},{peg['ly']:.2f},{peg['lz']:.2f}) hole=({hole['x']:.2f},{hole['y']:.2f}) d=({dx:.2f},{dy:.2f})")
        if abs(dx) < 0.5 and abs(dy) < 0.5:
            break
        if not step_chunk("right", dx, dy, 0):
            log("ABORT: socket alignment step failed")
            sys.exit(1)

    # 4. Insert peg fully; use vision lower-end z and force to detect bottom
    max_insert_steps = 20
    for i in range(max_insert_steps):
        vis = call("vision", "locate")
        hole, peg = parse_vision(vis)
        fr = call("robot", "force", "right")
        f = parse_force(fr)
        if hole and peg:
            log(f"  insert step {i}: peg_lz={peg['lz']:.2f}, hole_top={hole['top_z']:.2f}, Fz={f['Fz'] if f else '?'}")
        if peg and peg["lz"] <= 16.0:
            log("  Reached insertion depth target (peg lower end <= 16 mm).")
            break
        if f and abs(f["Fz"]) > 9.0:
            log(f"  Force threshold reached (Fz={f['Fz']:.1f} N), assuming bottomed.")
            break
        # choose vertical step: faster above socket, gentle near/inside
        if peg and peg["lz"] > 60.0:
            dz = -5.0
        else:
            dz = -4.0
        r = call("robot", "step", "right", "0", "0", f"{dz:.3f}")
        log(f"  step down {dz:.1f}: ok={r.get('ok')} {r.get('text','').strip()}")
        if not r.get("ok"):
            log("  Step reported failure (force limit?). Checking force.")
            fr = call("robot", "force", "right")
            f2 = parse_force(fr)
            if f2 and abs(f2["Fz"]) > 5:
                log("  Force is high; likely bottomed/contact. Stopping.")
                break
            else:
                log("  Step failed but force is low; aborting.")
                sys.exit(1)

    log("=== Insertion sequence complete ===")
    st = parse_status(call("robot", "status"))
    vis = call("vision", "locate")
    hole, peg = parse_vision(vis)
    log(f"Final status: {st}")
    log(f"Final vision: hole={hole}, peg={peg}")

if __name__ == "__main__":
    main()
